def _parse_html_to_end(state: BlockState, end_marker: str, start_pos: int
    ) ->int:
    end_pos = state.src.find(end_marker, start_pos)
    if end_pos != -1:
        return end_pos + len(end_marker)
    # If end marker not found, check if we're at the end of the document
    if start_pos >= state.cursor_max:
        return state.cursor_max
    # Find the next newline to avoid infinite loops
    next_newline = state.src.find('\n', start_pos)
    if next_newline != -1:
        return next_newline + 1
    return state.cursor_max
